def validate_product(manifest, contract, previous_contract):
    errors = []
    # 1) ownership & SLOs are mandatory (global policy)
    if not manifest['metadata'].get('owner'):
        errors.append('missing owner')
    if 'slo' not in manifest['spec']:
        errors.append('missing SLOs')
    # 2) all PII columns must be declared and classified
    declared_pii = set(manifest['spec']['governance'].get('pii', []))
    schema_pii = {c['name'] for c in contract['schema'] if c.get('pii')}
    if schema_pii - declared_pii:
        errors.append(f'undeclared PII: {schema_pii - declared_pii}')
    # 3) enforce backward-compatible schema evolution
    if previous_contract:
        old = {c['name'] for c in previous_contract['schema']}
        new = {c['name'] for c in contract['schema']}
        removed = old - new
        if removed and contract['evolution']['compatibility'] == 'backward':
            errors.append(f'breaking change: removed columns {removed}')
    if errors:
        raise PolicyViolation(errors)   # blocks publish in CI/CD
    return 'APPROVED'
